parameters.jsCode:
const input = $input.first().json;
const cand = $('[Rerank] Split Candidates').first().json;
let s;
try {
  const raw = input.choices[0].message.content;
  s = JSON.parse(raw);
} catch (e) {
  s = {};
}
// Guard: if the AI response is missing/malformed fields (undefined, wrong
// shape, non-numeric), fall back to 0 per field instead of letting NaN
// silently turn into NULL when this reaches Postgres.
const skills = Number(s.skills_score) || 0;
const experience = Number(s.experience_score) || 0;
const projects = Number(s.projects_score) || 0;
s.skills_score = skills; s.experience_score = experience; s.projects_score = projects;
s.matched_skills = s.matched_skills || []; s.missing_skills = s.missing_skills || [];
const weighted = Math.round((skills*0.4) + (experience*0.35) + (projects*0.25));
return [{ json: {
  candidate_id: cand.id, application_id: cand.application_id, name: cand.name, email: cand.email,
  skills_score: s.skills_score, experience_score: s.experience_score, projects_score: s.projects_score,
  matched_skills: s.matched_skills || [], missing_skills: s.missing_skills || [],
  weighted_score: weighted
} }];

const all = $input.all().map(i => i.json);
all.sort((a,b) => b.weighted_score - a.weighted_score);
return all.slice(0, 5).map(c => ({ json: c }));

const raw = $input.first().json.choices[0].message.content;
let ex; try { ex = JSON.parse(raw).explanations; } catch(e) { ex = {}; }
const top5 = $('[Rerank] Sort & Take Top 5').all().map(i => i.json);
return top5.map(c => ({ json: { ...c, explanation: ex[c.candidate_id] || '' } }));

const raw = $input.first().json.choices[0].message.content;
