parameters.query:
SELECT c.name, c.email, a.score, a.matched_skills, a.missing_skills, a.stage
FROM candidates c JOIN applications a ON a.candidate_id = c.id
ORDER BY c.embedding <=> $1::vector LIMIT 5;

SELECT c.name, a.score, a.ai_summary, a.matched_skills, a.missing_skills, a.ai_explanation
FROM candidates c JOIN applications a ON a.candidate_id = c.id
WHERE c.name ILIKE $1 LIMIT 1;

