const raw = $input.first().json.choices[0].message.content;
let s; try { s = JSON.parse(raw); } catch(e) { s = { sentiment:'neutral', feedback_quality_score:50, key_strengths:[], key_concerns:[] }; }
const iv = $('[Hiring] Get Interview + Application Data').first().json;
const sentimentBonus = s.sentiment === 'positive' ? 15 : s.sentiment === 'negative' ? -15 : 0;
const finalScore = Math.max(0, Math.min(100, Math.round(((iv.score || 50) * 0.5) + ((iv.rating || 3) * 20 * 0.3) + (s.feedback_quality_score * 0.2) + sentimentBonus)));
return [{ json: { ...iv, sentiment_analysis: s, final_score: finalScore } }];

